import { createContext, useContext, useEffect, useState, type ReactNode } from 'react'
import { supabase } from '@/integrations/supabase/client'
import { useAuth } from './AuthProvider'
import { useTenant } from './TenantProvider'
import { centralUsersService, type CentralUser } from '@/integrations/supabase/centralUsers'
import { tenantMembershipsService, type TenantMembership } from '@/integrations/supabase/tenantMemberships'
import { workplacesService } from '@/integrations/supabase/workplaces'
import type { Workplace } from '@/entities/workspace/types'

export type IdentityStatus =
  | 'loading'
  | 'unauthenticated'
  | 'no_central_user'            // auth ok, no central_users row → run bootstrap SQL
  | 'no_tenant_access'           // no active tenant_memberships row
  | 'admin_without_membership'   // user_roles has super_admin but no membership
  | 'no_workspace'               // membership ok, tenant has zero workspaces
  | 'ready'

type Role = { role: string; tenant_id: string | null }

type IdentityContextValue = {
  centralUser: CentralUser | null
  activeTenantId: string | null
  tenantMemberships: TenantMembership[]
  activeWorkspace: Workplace | null
  workspaces: Workplace[]
  roles: Role[]
  status: IdentityStatus
  error: string | null
  refresh: () => void
}

const IdentityContext = createContext<IdentityContextValue>({
  centralUser: null,
  activeTenantId: null,
  tenantMemberships: [],
  activeWorkspace: null,
  workspaces: [],
  roles: [],
  status: 'loading',
  error: null,
  refresh: () => {},
})

export function useIdentity() {
  return useContext(IdentityContext)
}

/**
 * Read-only identity/access context.
 *
 * This provider NEVER inserts into central_users, tenant_memberships,
 * user_roles, workspaces, or object_memberships. Those rows are provisioned
 * out-of-band:
 *   - Dev/admin: supabase/sql/bootstrap_super_admin.sql
 *   - TODO(production): auth.users trigger, SECURITY DEFINER RPC, or
 *     service-role Edge Function.
 */
export function IdentityProvider({ children }: { children: ReactNode }) {
  const { user, isLoading: authLoading } = useAuth()
  const { manifest, isLoading: tenantLoading, error: tenantError } = useTenant()
  const activeTenantId =
    manifest?.tenantId && /^[0-9a-f-]{36}$/i.test(manifest.tenantId) ? manifest.tenantId : null

  const [centralUser, setCentralUser] = useState<CentralUser | null>(null)
  const [tenantMemberships, setTenantMemberships] = useState<TenantMembership[]>([])
  const [workspaces, setWorkspaces] = useState<Workplace[]>([])
  const [activeWorkspace, setActiveWorkspace] = useState<Workplace | null>(null)
  const [roles, setRoles] = useState<Role[]>([])
  const [status, setStatus] = useState<IdentityStatus>('loading')
  const [error, setError] = useState<string | null>(null)
  const [nonce, setNonce] = useState(0)

  useEffect(() => {
    let cancelled = false

    async function run() {
      if (authLoading || tenantLoading) {
        setStatus('loading')
        return
      }
      if (!user) {
        setStatus('unauthenticated')
        setCentralUser(null)
        setTenantMemberships([])
        setWorkspaces([])
        setActiveWorkspace(null)
        setRoles([])
        return
      }
      if (!activeTenantId) {
        setError(tenantError ?? 'This tenant is not provisioned. Ask an admin to create the tenants row.')
        setStatus('no_tenant_access')
        return
      }

      setError(null)
      try {
        // 1. central_users — READ ONLY.
        const cu = await centralUsersService.get(user.id)
        if (cancelled) return
        setCentralUser(cu)
        if (!cu) {
          setError(
            'Your account is signed in but has no profile yet. Run supabase/sql/bootstrap_super_admin.sql or ask an admin to provision your central_users row.',
          )
          setStatus('no_central_user')
          return
        }

        // 2. tenant_memberships — READ ONLY.
        const memberships = await tenantMembershipsService.listForUser(user.id)
        if (cancelled) return
        setTenantMemberships(memberships)
        const activeMembership = memberships.find(
          (m) => m.tenant_id === activeTenantId && m.status === 'active',
        )

        // 3. user_roles — READ ONLY.
        const { data: roleRows, error: roleErr } = await supabase
          .from('user_roles')
          .select('role, tenant_id')
          .eq('user_id', user.id)
        if (roleErr) console.warn('[identity] user_roles fetch failed:', roleErr.message)
        const allRoles = (roleRows ?? []) as Role[]
        const filtered = allRoles.filter(
          (r) => r.tenant_id === null || r.tenant_id === activeTenantId,
        )
        if (cancelled) return
        setRoles(filtered)

        if (!activeMembership) {
          const hasSuperAdmin = allRoles.some(
            (r) =>
              r.role === 'super_admin' &&
              (r.tenant_id === null || r.tenant_id === activeTenantId),
          )
          if (hasSuperAdmin) {
            setError(
              'Admin role exists, but tenant membership is missing. Run supabase/sql/bootstrap_super_admin.sql.',
            )
            setStatus('admin_without_membership')
          } else {
            setError('You do not have an active membership for this tenant.')
            setStatus('no_tenant_access')
          }
          return
        }

        // 4. workspaces — READ ONLY.
        const ws = await workplacesService.listWorkplaces(activeTenantId)
        if (cancelled) return
        setWorkspaces(ws)
        setActiveWorkspace(ws[0] ?? null)

        setStatus(ws.length === 0 ? 'no_workspace' : 'ready')
      } catch (e) {
        if (cancelled) return
        const msg = e instanceof Error ? e.message : String(e)
        console.error('[identity] read failed:', msg)
        setError(msg)
        setStatus('no_tenant_access')
      }
    }

    run()
    return () => {
      cancelled = true
    }
  }, [authLoading, tenantLoading, user, activeTenantId, tenantError, nonce])

  return (
    <IdentityContext.Provider
      value={{
        centralUser,
        activeTenantId,
        tenantMemberships,
        activeWorkspace,
        workspaces,
        roles,
        status,
        error,
        refresh: () => setNonce((n) => n + 1),
      }}
    >
      {children}
    </IdentityContext.Provider>
  )
}
